def count_partitions():
    target = 7
    coins = [1, 3, 4]
    # dp[i] will store the number of ways to make sum i using the coins considered so far
    dp = [0] * (target + 1)
    dp[0] = 1  # One way to make sum 0: use no coins

    for coin in coins:
        for i in range(coin, target + 1):
            dp[i] += dp[i - coin]
